/* ---------- Terminal stream ---------- */
/* the shell commands the agent runs, as a compact terminal: where it runs and how it is going in the header, then each
   command with its output streaming in under it, and an exit code or a check with how long it took. Output longer than
   five lines folds to its last four. The type and rhythm are Code viewer's: 12px mono on a 1.8 line height */
/* a terminal of a set height: the output scrolls under the header and keeps to its newest line, so the card is the same
   size from the first command to the last */
.tmx{overflow:hidden;display:flex;flex-direction:column;height:420px}
.tmx-h{display:flex;align-items:center;gap:var(--s-2);height:44px;padding:0 var(--s-2) 0 14px;border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent)}
.tmx-ic{display:grid;place-items:center;color:var(--fg2);flex:none}
.tmx-cwd{min-width:0;flex:0 1 auto;font-family:var(--mono);font-size:12px;color:var(--fg2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmx-st{display:inline-flex;align-items:center;gap:6px;min-width:0;font-size:12px;color:var(--muted);white-space:nowrap}
.tmx-st .g{display:grid;place-items:center;flex:none}
.tmx-st .spin{width:10px;height:10px}
.tmx-st.ok .g{color:var(--ok)}
.tmx-h .sp{flex:1}
.tmx-body{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:var(--s-2) 0;font-family:var(--mono);font-size:12px;line-height:1.8;scrollbar-width:thin;scrollbar-color:var(--rail) transparent}
.tmx-body::-webkit-scrollbar{width:8px}
.tmx-body::-webkit-scrollbar-track{background:transparent}
.tmx-body::-webkit-scrollbar-thumb{background:var(--rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--r-pill)}
:root:not([data-style="soft"]) .tmx-body:not(:where([data-style="soft"],[data-style="soft"] *))::-webkit-scrollbar-thumb{border-radius:0}
.tmx-blk+.tmx-blk{margin-top:var(--s-1)}
.tmx-cmd{display:flex;align-items:center;gap:var(--s-2);padding:0 14px}
.tmx-p{width:12px;flex:none;display:grid;place-items:center;color:var(--muted)}
.tmx-c{flex:1;min-width:0;font-weight:500;color:var(--fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmx-m{display:inline-flex;align-items:center;gap:6px;font-family:var(--sans);font-size:12px;color:var(--muted);white-space:nowrap;flex:none}
.tmx-m .g{display:grid;place-items:center}
.tmx-m .spin{width:10px;height:10px}
.tmx-m .ok{color:var(--ok)}
.tmx-m .add{color:var(--add)}.tmx-m .del{color:var(--del)}
/* the output wraps inside the panel, so a long line never pushes the page sideways */
.tmx-o{padding:0 14px 0 34px;color:var(--fg2);white-space:pre-wrap;overflow-wrap:anywhere}
.tmx-l.ok{color:var(--ok)}.tmx-l.bad{color:var(--bad)}.tmx-l.mu{color:var(--muted)}
.tmx-more{display:flex;align-items:center;gap:6px;margin-left:34px;font-family:var(--sans);font-size:12px;line-height:inherit;color:var(--muted);transition:color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.tmx-more:hover{color:var(--fg)}}
.tmx-more svg{transition:transform var(--t) var(--ease)}
.tmx-more[aria-expanded="true"] svg{transform:rotate(180deg)}
/* folded lines are hidden once they have folded away, so nothing measures the clipped part as if it were drawn */
.tmx-blk .fold.shut>div{visibility:hidden;transition:visibility 0s var(--t)}
/* what the agent says between commands: its spark in the accent and its words, which shimmer while it is still working it out */
.tmx-note{margin:var(--s-2) 14px;padding-left:20px;font-family:var(--sans);font-size:12.5px;line-height:1.5;color:var(--fg2);display:flex;gap:var(--s-2)}
.tmx-note>svg{color:var(--accent-fg,var(--accent));flex:none;margin-top:3px}
.tmx-note .shim{font-size:inherit}
.tmx-f{display:flex;align-items:center;gap:var(--s-2);padding:10px 14px;border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:13px}
.tmx-f .g{display:grid;place-items:center;flex:none;color:var(--ok)}
.tmx-f.stop .g{color:var(--muted)}.tmx-f.bad .g{color:var(--bad)}
/* the run's state in the header is a tag in its colour: the accent while it runs, green once it passes, red if it failed */
.tmx-st{height:22px;padding:0 var(--s-2);border-radius:var(--r-tag);background:var(--chip);color:var(--fg2);transition:background .3s,color .3s}
.tmx.live .tmx-st{background:var(--accent-bg);color:var(--accent-fg,var(--fg))}
.tmx-st.ok,.tmx-st.ok .g{background:var(--ok-bg);color:var(--ok)}
.tmx-st.bad,.tmx-st.bad .g{background:var(--bad-bg);color:var(--bad)}
/* while it runs, a light sweeps along the header's lower edge */
.tmx-h{position:relative}
.tmx-h::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--accent-mark,var(--accent)),transparent) 0 0/40% 100% no-repeat;opacity:0;transition:opacity .4s;pointer-events:none}
.tmx.live .tmx-h::after{opacity:1;animation:tmxsweep 1.8s var(--ease-io) infinite}
@keyframes tmxsweep{from{background-position:-60% 0}to{background-position:160% 0}}
/* the output sits on a faint code surface */
.tmx-body{background:color-mix(in srgb,var(--fg) 2.5%,var(--surface))}
/* each command and edit has a line down its left in how it went: the accent while it runs, green, red, grey once stopped */
.tmx-blk{position:relative}
.tmx-blk::before{content:"";position:absolute;left:6px;top:4px;bottom:4px;width:2px;border-radius:1px;background:var(--rail);transition:background .3s}
.tmx-blk[data-s="run"]::before{background:var(--accent-mark,var(--accent));animation:tmxpulse 1.4s var(--ease-io) infinite}
.tmx-blk[data-s="ok"]::before{background:color-mix(in srgb,var(--ok) 70%,transparent)}
.tmx-blk[data-s="bad"]::before{background:var(--bad)}
.tmx-blk[data-s="edit"]::before{background:var(--merge)}
@keyframes tmxpulse{50%{opacity:.35}}
.tmx-p{color:var(--accent-fg,var(--fg));font-weight:500}
.tmx-blk[data-s="edit"] .tmx-p{color:var(--merge)}
/* an edit shows the lines it changed, removed in red and added in green, each on its own tint */
.tmx-df{margin:2px 14px var(--s-1) 34px;border-radius:var(--r-sm);overflow:hidden}
.tmx-df div{padding:0 var(--s-2);white-space:pre-wrap;overflow-wrap:anywhere;color:var(--fg2)}
.tmx-df .a{background:color-mix(in srgb,var(--add) 10%,transparent)}.tmx-df .a::first-letter{color:var(--add)}
.tmx-df .d{background:color-mix(in srgb,var(--del) 10%,transparent)}.tmx-df .d::first-letter{color:var(--del)}
/* a block cursor blinks after the newest line while the run goes on */
.tmx.live .tmx-body::after{content:"";display:block;width:7px;height:14px;margin:var(--s-1) 0 0 34px;background:var(--fg2);animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .tmx-h:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:repeating-linear-gradient(90deg,var(--accent-mark) 0 6px,transparent 6px 12px);animation:tmxmarch .6s steps(4) infinite}
@keyframes tmxmarch{to{background-position:12px 0}}
:root:not([data-style="soft"]) .tmx-blk:not(:where([data-style="soft"],[data-style="soft"] *))::before{width:1px}
:root:not([data-style="soft"]) .tmx-blk[data-s="run"]:not(:where([data-style="soft"],[data-style="soft"] *))::before{animation:bpblink 1.1s steps(1,end) infinite}
@container (max-width:420px){.tmx-ic{display:none}.tmx-h{padding-left:var(--s-3)}.tmx-cmd{padding:0 var(--s-3)}.tmx-o{padding:0 var(--s-3)}.tmx-more{margin-left:var(--s-3)}.tmx-note{margin-inline:var(--s-3)}.tmx-f{padding-inline:var(--s-3)}.tmx-df{margin-left:var(--s-3);margin-right:var(--s-3)}.tmx-blk::before{left:3px}.tmx.live .tmx-body::after{margin-left:var(--s-3)}}

DM.def('terminal-stream', (r, c) => {
  const IC = { term:I('term'), stop:I('stop','xs'), copy:I('copy') };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => IC[k] || m);
  const root = $('.tmx', r), body = $('.tmx-body', r), st = $('.tmx-st', r), sv = $('.tmx-sv', r), stop = $('.tmx-stop', r), cp = $('.tmx-cp', r), ff = $('.tmx-ff', r), foot = $('.tmx-f', r);
  // what the agent does: each command with the lines it prints and how long it takes, then the one line where it says what
  // went wrong and the edit that fixes it. [text, tone] marks a line ok (green), bad (red) or mu (grey)
  const F = (n, kb) => 'dist/' + n.padEnd(22) + kb.padStart(6) + ' kB';
  const BUILD = [['> acme-web@2.4.0 build', 'mu'], ['> vite build', 'mu'], 'vite v6.2.1 building for production...', 'transforming...', ['✓ 1284 modules transformed.', 'ok'], 'rendering chunks...', 'computing gzip size...',
    ...[['index.html', '0.46'], ['assets/Home-1c9e.js', '3.12'], ['assets/Pricing-3f9a.js', '12.40'], ['assets/Cart-7b21.js', '9.86'], ['assets/Account-a04d.js', '7.31'], ['assets/Billing-52ce.js', '6.94'],
      ['assets/Bills-e8f3.js', '5.27'], ['assets/Team-0d6a.js', '4.88'], ['assets/Prefs-9a1b.js', '6.02'], ['assets/Docs-44f0.js', '8.15'], ['assets/Search-b7c2.js', '2.96'], ['assets/Modal-61de.js', '1.84'],
      ['assets/Chart-ef09.js', '21.73'], ['assets/Table-3a7e.js', '11.09'], ['assets/Form-c1d4.js', '4.41'], ['assets/Toast-8e2f.js', '1.12'], ['assets/dates-29bb.js', '18.30'], ['assets/vendor-8c1e.js', '98.12'],
      ['assets/index-4f2a.js', '42.31'], ['assets/index-9b7d.css', '18.92']].map(([n, kb]) => F(n, kb)), ['✓ built in 6.1s', 'ok']];
  const S = [
    { cmd:'npm install', ms:1900, out:['added 412 packages in 1.9s', 'found 0 vulnerabilities'] },
    { cmd:'npm run build', ms:6100, out:BUILD },
    { cmd:'npm test', ms:3400, exit:1, out:[['RUN  v3.0.5 ~/acme/web', 'mu'], ['✓ src/lib/cart.test.ts (14 tests)', 'ok'], ['× src/lib/price.test.ts (1 failed)', 'bad'], ['  × formats a yearly price', 'bad'],
      ['    Expected: "$240/yr"', 'ok'], ['    Received: "$240.00/yr"', 'bad'], ['Tests  1 failed | 23 passed (24)', 'bad']] },
    { note:'The test expects whole dollars, but formatPrice always adds cents. Dropping them for round amounts.', ms:1500 },
    { edit:'src/lib/price.ts', add:2, del:1, ms:1500, diff:["- return `$${n.toFixed(2)}/${per}`", '+ const v = Number.isInteger(n) ? String(n) : n.toFixed(2)', '+ return `$${v}/${per}`'] },
    { cmd:'npm test', ms:2900, out:[['✓ src/lib/cart.test.ts (14 tests)', 'ok'], ['✓ src/lib/price.test.ts (10 tests)', 'ok'], ['Tests  24 passed (24)', 'ok']] }
  ];
  // output longer than five lines folds to its last four, behind a button that says how many are hidden
  const TAIL = 4, GAP = 200;
  let vt = 0, halt = false, over = false;
  const log = [], ran = [];
  const clock = ms => { const s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
  const sec = ms => (ms / 1000).toFixed(1) + ' s';
  // time passes in steps of a quarter second at most, so the clock in the header keeps up; false once Stop is pressed
  const pass = async (ms, each) => {
    for (let t = 0; t < ms;){ if (halt) return false; const d = Math.min(250, ms - t); await c.wait(d); t += d; vt += d; if (!over) sv.textContent = 'Running · ' + clock(vt); each && each(t); }
    return !halt;
  };
  // a command or an edit: what it is on the left, a spinner and its time on the right
  function row(mark, text){
    const el = html(`<div class="tmx-blk" data-s="run"><div class="tmx-cmd"><span class="tmx-p">${mark}</span><span class="tmx-c"></span><span class="tmx-m"><span class="g"><span class="spin"></span></span><span class="t num"></span></span></div></div>`);
    $('.tmx-c', el).textContent = text; body.appendChild(el); enter(el); return el;
  }
  function lines(el){
    const more = html(`<button class="tmx-more" aria-expanded="false" hidden>${I('chev-d','xs')}<span></span></button>`), hid = html('<div class="fold shut"><div class="tmx-o"></div></div>'), tail = html('<div class="tmx-o"></div>');
    const inner = hid.firstElementChild; hid.inert = true; el.append(more, hid, tail);
    const label = () => { const n = inner.children.length, open = !hid.classList.contains('shut'); $('span', more).textContent = open ? 'Show fewer lines' : `Show ${n} more line${n > 1 ? 's' : ''}`; more.setAttribute('aria-expanded', open); };
    more.onclick = () => { hid.inert = hid.classList.toggle('shut'); label(); };
    return ([text, tone]) => {
      const l = document.createElement('div'); l.className = 'tmx-l' + (tone ? ' ' + tone : ''); l.textContent = text; tail.appendChild(l);
      if (inner.children.length + tail.children.length > TAIL + 1) while (tail.children.length > TAIL) inner.appendChild(tail.firstElementChild);
      if (inner.children.length){ more.hidden = false; label(); }
    };
  }
  const halted = el => { $('.tmx-m .g', el).innerHTML = '<span class="tag">Stopped</span>'; el.dataset.s = 'stop'; };
  function finish(how){
    over = true; stop.hidden = true; root.classList.remove('live');
    st.classList.toggle('ok', how === 'passed'); st.classList.toggle('bad', how === 'failed'); $('.g', st).innerHTML = I(how === 'passed' ? 'check' : 'stop', 'xs'); sv.textContent = how === 'passed' ? 'Passed' : how === 'failed' ? 'Failed' : 'Stopped';
    // each command counts once, however many times it ran
    const n = new Set(ran).size;
    $('.tmx-fs', foot).textContent = `${n} command${n === 1 ? '' : 's'} · ${clock(vt)} · ${how}`;
    foot.className = 'tmx-f' + (how === 'stopped' ? ' stop' : how === 'failed' ? ' bad' : ''); $('.g', foot).innerHTML = I(how === 'passed' ? 'ok' : how === 'failed' ? 'alert' : 'stop');
    ff.classList.remove('shut');
  }
  // new output keeps the log on its newest line, unless the person has scrolled up to read; then it stays where they are
  let pinned = true;
  const stick = () => { if (pinned) body.scrollTop = body.scrollHeight; };
  c.on(body, 'scroll', () => { pinned = body.scrollTop + body.clientHeight >= body.scrollHeight - 24; });
  const mo = new MutationObserver(stick); mo.observe(body, { childList:true, subtree:true }); c.offs.push(() => mo.disconnect());
  const ro = new ResizeObserver(stick); ro.observe(body); c.offs.push(() => ro.disconnect());
  stop.onclick = () => { halt = true; };
  cp.onclick = () => copied(cp, log.join('\n'));
  root.classList.add('live');
  c.run(async () => {
    let last = 0;
    for (const k of S){
      if (!await pass(GAP)) return finish('stopped');
      if (k.note){
        const n = html(`<div class="tmx-note">${I('spark','xs')}<span class="shim"></span></div>`), w = $('span', n); w.textContent = k.note; body.appendChild(n); enter(n); log.push('# ' + k.note);
        const ok = await pass(k.ms); w.classList.remove('shim');
        if (!ok) return finish('stopped');
        continue;
      }
      if (k.edit){
        const el = row(I('edit','xs'), 'Edit ' + k.edit); el.dataset.s = 'edit';
        if (!await pass(k.ms)){ halted(el); return finish('stopped'); }
        $('.tmx-m', el).innerHTML = `<span class="add">+${k.add}</span><span class="del">−${k.del}</span>`; log.push(`# Edited ${k.edit} (+${k.add} −${k.del})`);
        const df = document.createElement('div'); df.className = 'tmx-df';
        k.diff.forEach((d, i) => { const l = document.createElement('div'); l.className = d[0] === '+' ? 'a' : d[0] === '-' ? 'd' : ''; l.textContent = d; df.appendChild(l); enter(l, i * 90); });
        el.appendChild(df); log.push(...k.diff);
        continue;
      }
      const el = row('$', k.cmd), t = $('.tmx-m .t', el), add = lines(el), per = k.ms / k.out.length;
      ran.push(k.cmd); log.push('$ ' + k.cmd); t.textContent = sec(0);
      let at = 0;
      for (const ln of k.out){
        const ok = await pass(per, d => { t.textContent = sec(at + d); }); at += per;
        if (!ok){ add(['^C', 'mu']); log.push('^C'); halted(el); return finish('stopped'); }
        const pair = Array.isArray(ln) ? ln : [ln, '']; add(pair); log.push(pair[0]);
      }
      t.textContent = sec(k.ms); last = k.exit || 0;
      $('.tmx-m .g', el).innerHTML = k.exit ? `<span class="tag bad">Exit ${k.exit}</span>` : `<span class="ok">${I('check','xs')}</span>`; el.dataset.s = k.exit ? 'bad' : 'ok';
    }
    finish(last ? 'failed' : 'passed');
  });
  // the preview's story: the agent runs, fails a test, fixes it and passes; then the person copies the whole run
  c.story(async s => {
    await s.until(() => over);
    await s.beat(2);
    await s.tap(cp); await s.beat(3);
  });
});
